// 1. Serverless boot + edit — runs in every project (file://, no server).
//
// This is the page a user double-clicks: editor/neodoc-editor.html, generated by
// tools/bundle.js. If it boots with no console error and no uncaught page error,
// and the markdown input rules still turn typed text into canonical elements, then
// the bundle is intact and the inline editing path works in that engine.

import { test, expect } from '@playwright/test';
import { SERVERLESS_EDITOR, expectClean, watchPage } from './helpers.js';

test('boots from file:// with no console or page errors and renders the toolbar', async ({ page }) => {
  const noise = watchPage(page);

  await page.goto(SERVERLESS_EDITOR);
  // Public hooks and the toolbar the specs drive.
  await page.waitForFunction(() => !!window.neodocEditor);
  await expect(page.locator('#toolbar')).toBeVisible();
  for (const cmd of ['open', 'save', 'strong', 'em', 'h1', 'ul', 'img', 'comment', 'suggest', 'copy-cli']) {
    await expect(page.locator(`button[data-cmd="${cmd}"]`)).toBeVisible();
  }
  await expect(page.locator('#open-input')).toBeAttached();
  await expect(page.locator('#image-input')).toBeAttached();
  await expect(page.locator('#threads')).toBeAttached();
  // The ignored /doc probe failed, so the editor reports no document: proof the
  // page is usable without a server.
  await expect(page.locator('#st-state')).toContainText(/no file open/i);

  // Typing at the caret: nothing is injected, the caret is the user's click.
  await page.locator('body > p').first().click();

  await page.keyboard.type('# ');
  await page.keyboard.type('Typed title');
  await expect(page.locator('body > h1')).toHaveText('Typed title');

  await page.keyboard.press('Enter');
  await page.keyboard.type('**bold**');
  await expect(page.locator('body strong')).toHaveCount(1);
  await expect(page.locator('body strong')).toHaveText('bold');

  await page.keyboard.press('Enter');
  await page.keyboard.type('- ');
  await page.keyboard.type('item');
  await expect(page.locator('body > ul > li')).toHaveText('item');

  expectClean(noise);
});

test('a comment on a selection lands in the document and in the sidebar', async ({ page }) => {
  const noise = watchPage(page);

  await page.goto(SERVERLESS_EDITOR);
  await page.waitForFunction(() => !!window.neodocEditor);

  await page.locator('body > p').first().click();
  await page.keyboard.type('# ');
  await page.keyboard.type('Reviewed heading');
  await expect(page.locator('body > h1')).toHaveText('Reviewed heading');

  // Select the heading text the way a user would, then comment on the selection.
  await page.evaluate(() => {
    const heading = document.querySelector('body > h1');
    const range = document.createRange();
    range.selectNodeContents(heading);
    const selection = window.getSelection();
    selection.removeAllRanges();
    selection.addRange(range);
  });
  // `prompt()` returns the comment body; answering it is part of the flow.
  page.once('dialog', (dialog) => dialog.accept('Where does this come from?'));

  await page.locator('button[data-cmd="comment"]').click();

  const thread = page.locator('#threads li');
  await expect(thread).toHaveCount(1);
  await expect(thread).toContainText('Where does this come from?');
  await expect(thread).toContainText('Reviewed heading');
  // The anchor is a plain HTML element in the document, not editor state.
  await expect(page.locator('body mark[data-c="c1"]')).toHaveText('Reviewed heading');
  await expect(page.locator('#st-comments')).toHaveText('1 comments');
  await expect(page.locator('#no-comments')).toBeHidden();

  expectClean(noise);
});
